<script>
// A workspace's conversations, and one shell into the workspace itself.
//
// The conversations run in Extension Studio's agent pod, namespaced by this workspace's name -
// see conversations.ts for why that is where they are and how the Studio's drawer never sees
// them. They are there the moment the workspace exists: the agent pod is always up, so a
// conversation can be opened, and a prompt queued for it, while the workspace's own pod is
// still cloning and compiling.
//
// The shell is the other thing: a bash in the workspace's container, in its checkout, for when
// what is wanted is the tree rather than a conversation about it. It is the one row that does
// wait for the workspace's pod.
import { Banner } from '@components/Banner';
import DevTerminal from './DevTerminal.vue';
import StudioTerminal from './StudioTerminal.vue';
import DevList from './DevList.vue';
import DevModal from './DevModal.vue';
import ConversationHeader from './ConversationHeader.vue';
import {
  LABEL_WORKSPACE, WORKSPACE_CONTAINER, workspaceTerminalCommand
} from '../api';
import {
  listConversations, startConversation, endConversation, renameConversation, startedConversations, conversationStates, snapshotFromAnswer, statesFromSnapshot, STUDIO_CLUSTER, KUBECTL
} from '../conversations';
import { watch } from '../events';
import { CLI_CHOICES, cliMark } from '../agent-clis.mjs';
import { readPrefs } from '../prefs';
import { agentStateOf } from '../workspace-status';
import { prepareWorkspace } from '../reviews';
import { ensureWorkspaceReady } from '../workspace-tools';
import { ensureDefaultShare } from '../previews';
import { note } from '../dev-log.mjs';

const ROW_STATE = {
  open: 'running', connecting: 'starting', waiting: 'starting', closed: 'stopped'
};

/** The row key of the workspace's own shell, which is not a conversation. */
const SHELL = 'shell';

export default {
  name: 'WorkspaceConversations',

  components: {
    Banner, DevTerminal, StudioTerminal, DevList, DevModal, ConversationHeader
  },

  props: {
    workspace: {
      type:     Object,
      required: true,
    },
    logTail: {
      type:    String,
      default: '',
    },
  },

  async fetch() {
    await this.load();
  },

  data() {
    return {
      /** Which CLI the plain press of "New conversation" uses; '' reads as claude. */
      defaultCli: '',
      prepared: false,
      conversations: [],
      current:       '',
      states:        {},
      // The agent state of each conversation, by id, from the same poll the rail and the
      // sidebar use (conversationStates): what the header shows over the pane. `states` above
      // is the pane's own socket state (the row's dot); this is what claude is doing.
      agents:        {},
      stopAgents:    null,
      /** The current conversation blown up to fill the window (DevModal), when asked for. */
      popped:        false,
      error:         '',
      // The conversations that have run at least once (conversations.ts, startedConversations),
      // read while the workspace's pod is not up: their panes are shown regardless. And whether
      // the pod has been up while this page was open - once it has, every pane stays.
      started:       {},
      wasUp:         false,
    };
  },

  computed: {
    /** The CLIs the create control offers; a module constant is not visible to a template. */
    CLI_CHOICES: () => CLI_CHOICES,

    ready() {
      return this.workspace.state === 'running' || this.workspace.state === 'starting';
    },

    /**
     * The workspace's own pod is up, not merely on its way. A conversation's pane waits for this
     * rather than for `ready`: its opening prompt (a review, a fix) runs the moment claude starts,
     * and it has to run against a checkout that is there - a pane started while the pod is still
     * cloning and installing comes up on an empty tree, or on no pod at all.
     */
    fullyUp() {
      return this.workspace.state === 'running';
    },

    failing() {
      return this.workspace.state === 'error';
    },

    /**
     * Whether the open conversation's pane is on the page while the workspace's pod is not
     * fully up - which is when the banners above the pane say so beside it rather than instead
     * of it.
     */
    currentKeepsRunning() {
      const conversation = this.conversations.find((c) => c.id === this.current);

      return !!conversation && !this.fullyUp && this.paneReady(conversation);
    },

    progress() {
      return this.workspace.detail || 'Starting';
    },

    podLabels() {
      return { [LABEL_WORKSPACE]: this.workspace.name };
    },

    container() {
      return WORKSPACE_CONTAINER;
    },

    rows() {
      return [
        ...this.conversations.map((conversation) => {
          // Which CLI holds it, from the one list of them, so a strip with both in it says which
          // is which without opening a tab.
          return {
            key:   conversation.id,
            label: conversation.title,
            state: ROW_STATE[this.states[conversation.id]] || 'stopped',
            // The provider's own mark, so a list holding both says which is which at a glance.
            mark:  cliMark(conversation.cli),
          };
        }),
        // The shell needs a pod that has the terminal scripts mounted, which a preview's nginx
        // does not; a preview does not show this tab at all, but the row is guarded here too.
        ...(this.workspace.preview ? [] : [{
          key:   SHELL,
          label: 'Workspace shell',
          fixed: true,
          state: ROW_STATE[this.states[SHELL]] || (this.ready ? 'stopped' : 'starting'),
        }]),
      ];
    },

    showingShell() {
      return this.current === SHELL;
    },

    /** The conversation the pane is on, if it is a conversation rather than the shell. */
    currentConversation() {
      return this.conversations.find((conversation) => conversation.id === this.current) || null;
    },

    /**
     * Whether the workspace's shell can be reached through the agent pod.
     *
     * Every pane here is the Studio's, on the Studio's agent pod, for one reason: one pod means
     * one exec path and one cookie to authenticate it. The shell into the workspace's own
     * container goes the same way when it can - the agent pod has kubectl and a cluster-admin
     * account on its own cluster, so it execs into the workspace's pod from there. A workspace
     * on another cluster is out of that reach, and its shell opens directly, as it always did.
     */
    shellViaAgent() {
      return (this.workspace.cluster || 'local') === STUDIO_CLUSTER;
    },

    /** The argv the agent pod runs to land in the workspace's container: kubectl, then the workspace's own shell.sh. */
    shellViaAgentCommand() {
      return [
        ...KUBECTL,
        'exec', '-i', '-t', '-n', this.workspace.namespace, `deploy/${ this.workspace.namespace }`, '-c', WORKSPACE_CONTAINER, '--',
        ...this.shellCommand(),
      ];
    },
  },

  watch: {
    current(id) {
      this.rememberInRoute(id);
    },

    fullyUp(up) {
      if (up) {
        this.wasUp = true;
      }
    },
  },

  mounted() {
    // Which CLI this person holds conversations with, for the split button's plain press.
    readPrefs().then((prefs) => {
      this.defaultCli = prefs.cli || '';
    }).catch(() => undefined);

    /*
     * The agents' states, on the page's one socket rather than a beat of their own.
     *
     * The snapshot is the same document the rail and the sidebar read, so all three are now one
     * subscription that dev-api pushes when it changes. Fifteen seconds survives as the hub's
     * read floor and as this view's cadence while the socket is down, which is the beat this
     * used to keep unconditionally.
     */
    this.stopAgents = watch('/conversations', (answer) => this.showAgents(answer), { every: 15000 });
  },

  beforeUnmount() {
    this.stopAgents?.();
  },

  methods: {
    /**
     * What the snapshot the socket just pushed says this workspace's agents are doing.
     *
     * A null value is a bundle or a pod that cannot answer with a snapshot at all, and that is
     * the one case still worth an exec: `refreshAgents` keeps the old path for it, so a workspace
     * on an older agents half reports states exactly as it did before.
     */
    showAgents(answer) {
      // The push is dev-api's answer verbatim, so the guard and the keying it needs are the same
      // ones a fetch gets: `snapshotFromAnswer` is both, and returns null for the empty, stale or
      // failed listing that has to fall through to the exec rather than draw an empty list.
      const seen = snapshotFromAnswer(answer);

      if (!seen) {
        this.refreshAgents();

        return;
      }
      this.agents = this.byConversation(statesFromSnapshot(seen));
    },

    /** Which of this workspace's conversations are running, and what each agent is doing. */
    async refreshAgents() {
      const states = await conversationStates().catch(() => null);

      if (!states) {
        return;
      }
      this.agents = this.byConversation(states);
    },

    /** The states for this workspace alone, keyed by conversation id. */
    byConversation(states) {
      const next = {};

      for (const c of states) {
        if (c.workspace === this.workspace.name) {
          next[c.id] = agentStateOf(c);
        }
      }

      return next;
    },

    /**
     * Keep `?c=` on the URL in step with the conversation that is open.
     *
     * The tab is the hash here (see WorkspaceDetail for why that is not cosmetic), so the
     * conversation is a query parameter beside it and the hash has to be carried through the
     * replace by hand - `replace({ query })` alone drops it, which would put somebody back on
     * the first tab every time they picked a conversation.
     *
     * Guarded on the hash because this component stays mounted while another tab is showing:
     * without it, a poll that re-selected something in the background would rewrite the URL of
     * a page nobody was looking at.
     *
     * `replace` rather than `push`, so choosing a conversation is not a history entry to press
     * Back through.
     */
    rememberInRoute(id) {
      if (this.$route.hash && this.$route.hash !== '#conversations') {
        return;
      }

      const query = { ...this.$route.query };

      if (id) {
        query.c = id;
      } else {
        delete query.c;
      }

      if ((this.$route.query.c || '') === (query.c || '')) {
        return;
      }

      this.$router.replace({ query, hash: this.$route.hash }).catch(() => {});
    },

    /**
     * Whether a conversation's pane belongs on the page now.
     *
     * A conversation runs in the agent pod, not the workspace's, so the workspace's pod being
     * away - terminating for a re-render, OOM-killed, waiting on a busy node - is no reason to
     * take a running conversation off the page: it is still going, and taking the pane away
     * looked exactly like the conversation dying, over and over. What does wait for the pod is
     * a conversation that has never run, because the prompt it opens with runs the instant
     * claude starts and wants the checkout there.
     */
    paneReady(conversation) {
      return this.fullyUp || this.wasUp || !!this.started[conversation.id];
    },

    async load() {
      this.error = '';

      if (this.fullyUp) {
        this.wasUp = true;
      }

      try {
        this.conversations = await listConversations(this.workspace.name);
      } catch (e) {
        this.error = e.message || String(e);
        this.conversations = [];
      }

      // Only asked while the pod is away and before it has been seen up: both are answered
      // without it, and the exec into the agent pod is one more call on every poll otherwise.
      if (!this.fullyUp && !this.wasUp && this.conversations.length) {
        const started = await startedConversations(this.workspace.name).catch(() => new Set());

        this.started = Object.fromEntries([...started].map((id) => [id, true]));
      }

      if (!this.current || !this.rows.some((row) => row.key === this.current)) {
        // What the URL asked for, if it is still here, before falling back to the first. This
        // is what makes a reload - or a link somebody sent - come back to the conversation
        // that was being read rather than to whichever happens to be at the top.
        const asked = String(this.$route.query.c || '');

        this.current = (asked && this.rows.some((row) => row.key === asked) ? asked : '') ||
          this.conversations[0]?.id || SHELL;
      }

      // The workspace made ready for whatever gets typed into a pane: the harness's skills,
      // gh, the env. Once per page, in the background; a pane opened before it finishes is a
      // claude that starts a moment before its skills are all there.
      if (this.ready && !this.prepared) {
        this.prepared = true;
        prepareWorkspace(this.workspace.name)
          // Shared by default: the checkout built and put on a link, the first time it is ready.
          .then(() => ensureDefaultShare(this.$store, this.workspace.name, this.workspace.cluster || 'local').catch(() => {}))
          .catch((e) => {
            this.prepared = false;
            // A pod that is not up yet is the ordinary case on a new workspace, and the row
            // above already says it is starting; only a real failure is worth a banner.
            if (!/no running pod yet/.test(String(e?.message || e))) {
              this.error = `The workspace could not be prepared for the harness's skills: ${ e?.message || e }`;
              note('dev', 'preparing the workspace failed', e);
            }
          });
      }
    },

    /** shell.sh's four arguments (session, checkout, home) and then the mode: a shell, not claude. */
    shellCommand() {
      return [...workspaceTerminalCommand(this.workspace.name, 'shell'), 'shell'];
    },

    async newConversation(cli = '') {
      this.error = '';

      try {
        // Like the rail's +. What the page did as it opened may have believed a stamp, and this is
        // somebody about to work here, on whatever token and files the workspace has now.
        await ensureWorkspaceReady(this.workspace.name);

        const conversation = await startConversation(this.workspace.name, '', '', cli);

        this.conversations = [...this.conversations, conversation];
        this.current = conversation.id;
      } catch (e) {
        this.error = e.message || String(e);
      }
    },

    async closeConversation(key) {
      if (key === SHELL) {
        return;
      }

      this.error = '';

      try {
        await endConversation(this.workspace.name, key);
      } catch (e) {
        this.error = e.message || String(e);

        return;
      }

      this.conversations = this.conversations.filter((conversation) => conversation.id !== key);

      if (this.current === key) {
        this.current = this.conversations[this.conversations.length - 1]?.id || SHELL;
      }

      const states = { ...this.states };

      delete states[key];
      this.states = states;
    },

    /** A row's new name, from the list: the shell row is not a conversation and cannot be renamed. */
    async rename({ key, title }) {
      if (key === SHELL || !title) {
        return;
      }

      try {
        await renameConversation(this.workspace.name, key, title);
        this.conversations = this.conversations.map((entry) => (entry.id === key ? { ...entry, title } : entry));
      } catch (e) {
        this.error = e.message || String(e);
      }
    },

    onState(key, state) {
      this.states = { ...this.states, [key]: state };
    },
  },
};
</script>

<template>
  <div class="workspace-conversations">
    <!--
      The same column the sidebar's workspaces are, and for the same reasons: a conversation has
      a state worth a dot, is created from the heading, and can be closed from its own row. No
      heading text - the tab above says Conversations.
    -->
    <div class="workspace-conversations__list">
      <DevList
        label=""
        icon="icon-comment"
        :rows="rows"
        :current="current"
        create-label="New conversation"
        :create-options="CLI_CHOICES"
        :create-value="defaultCli"
        empty="No conversations"
        deletable
        renamable
        @select="current = $event"
        @create="newConversation"
        @delete="closeConversation"
        @rename="rename"
      />
    </div>
    <div class="workspace-conversations__pane">
      <!--
        The same controls a conversation has on the global page: its name (renamed in place),
        what its agent is doing, a way to open it larger, and a way to close it. The shell is
        not a conversation, so it has none of these.
      -->
      <ConversationHeader
        v-if="!showingShell && currentConversation"
        :conversation="currentConversation"
        :agent="agents[current] || 'none'"
        @rename="rename({ key: current, title: $event })"
        @popout="popped = true"
        @close="closeConversation(current)"
      />
      <Banner
        v-if="error"
        color="error"
        :label="error"
      />
      <!-- The shell is the one pane that waits for the workspace's own pod. -->
      <Banner
        v-if="showingShell && failing"
        color="error"
      >
        <p>This workspace is not staying up: {{ progress }}.</p>
        <p
          v-if="logTail"
          class="workspace-conversations__log"
        >
          {{ logTail }}
        </p>
      </Banner>
      <Banner
        v-else-if="showingShell && !ready"
        color="info"
      >
        <p>{{ progress }}. A workspace that clones a repository and installs it takes a few minutes on its first start.</p>
        <p
          v-if="logTail"
          class="workspace-conversations__log"
        >
          {{ logTail }}
        </p>
      </Banner>
      <!--
        A conversation waits for the workspace to be fully up before its pane starts. Its opening
        prompt runs the instant claude starts, so starting it against a pod that is still cloning
        and installing is what left a review sitting at an empty prompt. Until then this says what
        the workspace is doing, and the pane starts - and the prompt runs - on its own once it is
        up.
      -->
      <!--
        A conversation that is already running stays on the page while the workspace's pod is
        away: it runs in the agent pod, and only the commands it sends into the workspace fail
        until the pod is back. The banner says so beside the pane. A conversation that has not
        run yet is the other case, below: its pane waits.
      -->
      <Banner
        v-if="!showingShell && currentKeepsRunning"
        :color="failing ? 'error' : 'warning'"
      >
        <p>The workspace's pod is {{ failing ? 'not staying up' : 'away' }}: {{ progress }}. This conversation keeps running in the agent pod; the commands it runs in the workspace fail until the pod is back, which it does on its own.</p>
        <p
          v-if="failing && logTail"
          class="workspace-conversations__log"
        >
          {{ logTail }}
        </p>
      </Banner>
      <Banner
        v-else-if="!showingShell && failing"
        color="error"
      >
        <p>This workspace is not staying up: {{ progress }}.</p>
        <p
          v-if="logTail"
          class="workspace-conversations__log"
        >
          {{ logTail }}
        </p>
      </Banner>
      <Banner
        v-else-if="!showingShell && !fullyUp"
        color="info"
      >
        <p>{{ progress }}. This conversation starts on its own once the workspace is up - a first start clones the repository and installs it, which takes a few minutes.</p>
        <p
          v-if="logTail"
          class="workspace-conversations__log"
        >
          {{ logTail }}
        </p>
      </Banner>
      <!--
        Every conversation is the Studio's own pane onto its agent pod, placed here. The Studio
        hands the component over (conversations.ts, studioApi); what this says is which
        conversation, by its id. A pane is mounted once the workspace is fully up, or once it
        has been while this page was open, or - whatever the pod is doing - when the
        conversation has already run (paneReady): the opening prompt it carries never starts
        against a half-built tree, and a running conversation is never taken off the page.
      -->
      <template
        v-for="conversation in conversations"
        :key="conversation.id"
      >
        <StudioTerminal
          v-if="paneReady(conversation) && !(popped && conversation.id === current)"
          v-show="conversation.id === current"
          class="workspace-conversations__terminal"
          :session="conversation.id"
          :mode="conversation.cli || ''"
          :command="conversation.attach.command"
          @state="onState(conversation.id, $event)"
        />
      </template>
      <StudioTerminal
        v-if="ready && shellViaAgent"
        v-show="showingShell"
        key="shell-via-agent"
        class="workspace-conversations__terminal"
        :command="shellViaAgentCommand"
        @state="onState('shell', $event)"
      />
      <DevTerminal
        v-else-if="ready"
        v-show="showingShell"
        key="shell"
        class="workspace-conversations__terminal"
        :namespace="workspace.namespace"
        :labels="podLabels"
        :own="workspace.name"
        :container="container"
        :command="shellCommand()"
        :cluster="workspace.cluster"
        @state="onState('shell', $event)"
      />
      <!-- The larger view of the current conversation, over the page rather than instead of it. -->
      <DevModal
        v-if="popped && currentConversation"
        size="large"
        :title="`${ workspace.name } · ${ currentConversation.title || 'conversation' }`"
        @close="popped = false"
      >
        <div class="workspace-conversations__popped">
          <StudioTerminal
            :key="`pop-${ current }`"
            class="workspace-conversations__terminal"
            :session="current"
            :mode="currentConversation.cli || ''"
            :command="currentConversation.attach.command"
            @state="onState(current, $event)"
          />
        </div>
      </DevModal>
    </div>
  </div>
</template>

<style lang="scss" scoped>
  .workspace-conversations {
    display:    flex;
    flex:       1 1 auto;
    min-height: 0;

    &__list {
      display:        flex;
      flex-direction: column;
      flex:           0 0 220px;
      overflow-y:     auto;
      border-right:   1px solid var(--border);
    }


    &__pane {
      display:        flex;
      flex-direction: column;
      flex:           1 1 auto;
      min-width:      0;
    }

    &__log {
      overflow:      hidden;
      margin:        var(--dev-space-1) 0 0 0;
      font-family:   monospace;
      font-size:     12px;
      white-space:   nowrap;
      text-overflow: ellipsis;
    }

    &__terminal {
      flex:       1 1 auto;
      min-height: 0;
    }

    // The blown-up conversation inside DevModal fills the panel it is given, and the panel is
    // nearly the window: the reason to blow a conversation up is to read more of it.
    &__popped {
      display:        flex;
      flex-direction: column;
      height:         calc(100vh - 90px);
    }
  }

/* ── Phones: one column. A list beside a terminal is two things too narrow to use, so the
   conversations become a row that scrolls across the top and the pane takes the rest. */
@media (max-width: 760px) {
  .workspace-conversations {
    flex-direction: column;

    &__list {
      flex:          0 0 auto;
      max-height:    132px;
      overflow-y:    auto;
      border-right:  0;
      border-bottom: 1px solid var(--border);
    }

    &__pane { min-height: 60vh; }
  }
}
</style>
