<script>
// Inline discussion for one pending review comment, or for a few selected lines: the chat onto a
// conversation scoped to that comment, opened as soon as Discuss is pressed.
//
// What the agent needs to know - the comment, the file and line, the routes it may use - is given
// to it quietly (startDiscussion stages it; the pane's hook hands it over with the first prompt),
// so the chat begins with the person's own first message rather than with a paragraph of context
// they never wrote. There used to be an opener box here first, which was the only way to say
// something before that paragraph went in; with the paragraph gone, the chat's own box is it.
//
// The harness ran these in its own container; here each is a conversation in the workspace,
// namespaced like the rest (see conversations.ts) so the Studio's drawer never lists it, and
// drawn by the Studio's own pane (StudioTerminal). Self-contained so several can run side by
// side under different comments. The conversation persists in the agent pod; the panel above
// remembers which conversation belongs to which comment, so closing and reopening reattaches.
import { Banner } from '@components/Banner';
import StudioTerminal from '../StudioTerminal.vue';
import PrButton from './PrButton.vue';
import {
  startDiscussion, discussPrompt, linesPrompt, DEFAULT_REPO
} from '../../reviews';
import { paneCommand } from '../../conversations';

export default {
  name: 'CommentDiscussion',

  components: {
    Banner, StudioTerminal, PrButton
  },

  emits: ['close', 'session'],

  props: {
    pr: {
      type:     Number,
      required: true,
    },
    repo: {
      type:    String,
      default: DEFAULT_REPO,
    },
    /** The workspace whose conversations this joins. */
    workspace: {
      type:     String,
      required: true,
    },
    /** Either a filed comment, or a bare line range - a conversation about code with nothing filed. */
    comment: {
      type:    Object,
      default: null,
    },
    lines: {
      type:    Object,
      default: null,
    },
    /**
     * Where `comment` lives, which decides what the agent is told it may do with it.
     *
     * `local` is a finding in dev-api's store and is the default, because that is what every
     * caller but one has. `github` is a draft reply in the person's unsubmitted review, which
     * the agent cannot write to - see discussPrompt.
     */
    lives: {
      type:    String,
      default: 'local',
    },
    initialMessage: {
      type:    String,
      default: '',
    },
    /** A conversation already opened for this comment - reattach rather than ask for an opener. */
    session: {
      type:    String,
      default: '',
    },
  },

  data() {
    return {
      draft:    this.initialMessage || '',
      starting: false,
      error:    '',
      current:  this.session || '',
      state:    '',
    };
  },

  computed: {
    where() {
      if (this.lines) {
        return `${ this.lines.path }:${ this.lines.startLine ? `${ this.lines.startLine }-${ this.lines.line }` : this.lines.line }`;
      }

      if (this.comment?.path) {
        return `${ this.comment.path }${ this.comment.line ? `:${ this.comment.line }` : '' }`;
      }

      return 'PR-level';
    },

    title() {
      if (this.lines) {
        return `Discuss ${ this.lines.path.split('/').pop() }:${ this.lines.line }`;
      }

      /*
       * "reply" rather than "comment" when it is a GitHub draft, and the word is load-bearing.
       *
       * The title is the only part of a discussion that survives a reload, so the rail recovers
       * which comment a conversation belongs to by parsing it back out (see `asks`). A finding's
       * id and a GitHub comment's id are different stores, and the rail keys the GitHub ones
       * `gh<id>` to keep them apart - so the title has to carry the same distinction, or a
       * question asked inside a draft-reply discussion comes back pointing at a finding that
       * does not exist.
       */
      return `Discuss ${ ({ github: 'reply', draft: 'draft' })[this.lives] || 'comment' } #${ this.comment?.id }`;
    },
  },

  mounted() {
    // Straight into the conversation: there is nothing to say before it opens any more.
    if (!this.current) {
      this.start();
    }
  },

  methods: {
    async start() {
      if (this.starting) {
        return;
      }

      this.starting = true;
      this.error = '';

      try {
        const message = this.draft.trim();
        const context = this.lines
          ? linesPrompt(this.pr, this.lines, '', this.repo, true)
          : discussPrompt(this.pr, this.comment, '', this.repo, this.lives, true);
        // The file and the line go into the conversation's id as well as into the context, so
        // that coming back to this comment tomorrow - or finding the pane in `tmux ls` - says
        // which line it was about. See conversation-id.mjs.
        const at = this.lines || this.comment || {};
        const conversation = await startDiscussion(this.workspace, this.title, context, {
          path: at.path || '', line: at.line || 0, label: `pr-${ this.pr }-comment`,
        }, message);

        this.current = conversation.id;
        this.draft = '';
        this.$emit('session', conversation.id);
      } catch (e) {
        this.error = e.message || String(e);
      } finally {
        this.starting = false;
      }
    },

    /** The argv of one conversation's pane: claude in the workspace's pod, reached through the agent pod. */
    paneFor(id) {
      return paneCommand(this.workspace, id);
    },
  },
};
</script>

<template>
  <div class="cd">
    <div class="cd__header">
      <span class="cd__title">Discussion</span>
      <span class="cd__loc">{{ where }}</span>
      <span
        v-if="current"
        class="cd__session"
      >{{ current }}</span>
      <PrButton
        variant="ghost"
        size="mini"
        class="cd__close"
        title="Close discussion (the conversation keeps running)"
        @click="$emit('close')"
      >
        &times;
      </PrButton>
    </div>
    <Banner
      v-if="error"
      color="error"
      :label="error"
      class="cd__error"
    />
    <div
      v-if="!current"
      class="cd__compose"
    >
      <span
        v-if="starting"
        class="cd__hint"
      >Opening a conversation about {{ lines ? 'these lines' : 'this comment' }}…</span>
      <PrButton
        v-else-if="error"
        variant="primary"
        size="sm"
        @click="start"
      >
        Try again
      </PrButton>
    </div>
    <StudioTerminal
      v-else
      :session="current"
      :command="paneFor(current)"
      class="cd__term"
      @state="state = $event"
    />
  </div>
</template>

